CREATE OR REPLACE PROCEDURE dswtdip2_actualization_dbo.sp_actualization_isms_postload_report_prepare_openbal()
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    TRUNCATE TABLE dswtdip2_actualization_dbo.actualization_isms_postload_report_prepare_openbal_cache;
    INSERT INTO dswtdip2_actualization_dbo.actualization_isms_postload_report_prepare_openbal_cache (counter, doc_date, pstg_date, type, cocd, curr, transldate, exchange_rate, ledger_group, period, reference, document_header_text, pk, gl_acct, specialgl, amount_in_doc_curr, amount_in_local_curr, amount_in_local_curr_2, ref_key_1, ref_key_2, ref_key_3, bline_date, purch_doc, purchasinglineitem, wbs_element, material, plnt, value_date, payt, "Order", cost_ctr, profit_ctr, partner_profit_center, tr_prt, assignment, text, quantity, uom, brand, subproduct_a, subproduct_b, franchise_area, business_center, revenue_type, event, vat_tax_code, "MVNO Partner", technology, "Charge Code", "Plan Type", name, street, country, "Postal Code", city, "Bank Key", "Bank Account", "Tax Number", "General Ledger Account", message, "Main Asset Number", "Base Tax Amount", "Withholding Tax Type", "Withholding Tax Code", "Payment Method", "New Company Code", "Local file for upload/download", "Error Flag", "core product", "Product lines", zdsp_order, zdsp_uniquekey, z_message, z_source_name)
